quiz.prompt:
Okumalar: 0 = çizgi yok, 1 = solda, 2 = ortada, 3 = sağda. Çizgi yokken sonYon == 0 ise 'B' (boşluk), değilse 'A' (arama) yazılır; çizgi varsa 'I' (izle). Bu kod ne yazar?

```
int sonYon = 0;
int okuma[] = {2, 1, 0, 0, 3};

void setup() {
  Serial.begin(9600);
  for (int i = 0; i < 5; i++) {
    int o = okuma[i];
    if (o == 0) {
      Serial.print(sonYon == 0 ? 'B' : 'A');
    } else {
      sonYon = (o == 1) ? -1 : (o == 3) ? 1 : 0;
      Serial.print('I');
    }
  }
  Serial.println();
}
void loop() {}
```

